92: export function PriceTrendChart({
93:   prices,
94:   times,
95:   commodityLabel,
96:   regionLabel,
97:   loading,
98: }: {
99:   prices: number[];
100:   times: string[];
101:   commodityLabel: string;
102:   regionLabel: string;
103:   loading: boolean;
104: }) {
105:   const [mounted, setMounted] = useState(false);
106:   useEffect(() => {
107:     setMounted(true);
108:   }, []);
109: 
110:   const data = useMemo(
111:     () =>
112:       prices.map((p, i) => {
113:         const t = times[i];
114:         const prev = i > 0 ? prices[i - 1] : null;
115:         const deltaPct =
116:           prev != null && prev !== 0 ? ((p - prev) / Math.abs(prev)) * 100 : null;
117:         return {
118:           label: t ? shortDate(t) : `T-${prices.length - 1 - i}`,
119:           full: t ? fullDate(t) : `T-${prices.length - 1 - i}`,
120:           harga: p,
121:           deltaPct,
122:         };
123:       }),
124:     [prices, times],
125:   );
126: 
127:   const avg = useMemo(
128:     () => (data.length > 0 ? data.reduce((s, d) => s + d.harga, 0) / data.length : 0),
129:     [data],
130:   );

